from pathlib import Path


def clean_names(names):
    result = {}
    for name in names:
        name = name.strip()
        if name:
            result.setdefault(name.casefold(), name)
    return list(result.values())


def write_labels(names, destination):
    names = clean_names(names)
    Path(destination).write_text(''.join(name + '\n' for name in names))
